<script setup lang="ts">
import { computed, onMounted, reactive, ref } from 'vue'
import { eliminarGrupo, eliminarSubgrupo, guardarCaracteristica, guardarGrupo, guardarSubgrupo, listarGrupos, obtenerGrupo, type GrupoItem, type Subgrupo } from '../services/gruposItems'
const rows=ref<GrupoItem[]>([]),criterio=ref(''),page=ref(1),lastPage=ref(1),total=ref(0),loading=ref(false),saving=ref(false),error=ref(''),success=ref(''),modal=ref(false),editing=ref<number|null>(null),detail=ref<GrupoItem|null>(null),subName=ref(''),subEditing=ref<number|null>(null),featureName=ref('')
const form=reactive({nombre:'',familia:'m' as 'm'|'a'|'s',vida_util:undefined as number|undefined,etiqueta:false,debe_deprec:undefined as number|undefined,haber_deprec:undefined as number|undefined,debe_revaluac:undefined as number|undefined,haber_revaluac:undefined as number|undefined})
const depreciation=computed(()=>form.vida_util?100/form.vida_util:0)
async function load(next=1){page.value=next;loading.value=true;error.value='';try{const r=await listarGrupos(criterio.value,next);rows.value=r.data;total.value=r.total;lastPage.value=r.last_page}catch(e){error.value=message(e)}finally{loading.value=false}}
function open(item?:GrupoItem){editing.value=item?.id||null;Object.assign(form,{nombre:item?.nombre||'',familia:item?.familia||'m',vida_util:item?.vida_util,etiqueta:item?.etiqueta||false,debe_deprec:item?.debe_deprec,haber_deprec:item?.haber_deprec,debe_revaluac:item?.debe_revaluac,haber_revaluac:item?.haber_revaluac});modal.value=true}
async function save(){if(!form.nombre.trim()){error.value='El nombre es obligatorio.';return}if(form.vida_util&&(form.vida_util<1||form.vida_util>99)){error.value='La vida útil debe estar entre 1 y 99 años.';return}if(editing.value&&rows.value.find(x=>x.id===editing.value)?.items_count&&form.nombre!==rows.value.find(x=>x.id===editing.value)?.nombre){error.value='No se puede cambiar el nombre porque existen ítems asociados.';return}saving.value=true;try{await guardarGrupo(editing.value,{...form});modal.value=false;success.value='Grupo guardado correctamente.';await load(editing.value?page.value:1)}catch(e){error.value=message(e)}finally{saving.value=false}}
async function remove(item:GrupoItem){if(item.items_count){error.value='No se puede eliminar el grupo porque existen ítems asociados.';return}if(!confirm(`¿Eliminar el grupo “${item.nombre}” y sus subgrupos vacíos?`))return;try{await eliminarGrupo(item.id);success.value='Grupo eliminado correctamente.';await load(page.value)}catch(e){error.value=message(e)}}
async function show(item:GrupoItem){try{detail.value=await obtenerGrupo(item.id);subName.value='';featureName.value=''}catch(e){error.value=message(e)}}
function editSub(item:Subgrupo){subEditing.value=item.id;subName.value=item.nombre}
async function saveSub(){if(!detail.value||!subName.value.trim())return;const current=detail.value.subgrupos?.find(x=>x.id===subEditing.value);if(current?.items_count&&current.nombre!==subName.value.trim()){error.value='No se puede renombrar un subgrupo con ítems asociados.';return}try{await guardarSubgrupo(detail.value.id,subEditing.value,subName.value.trim());success.value='Subgrupo guardado.';detail.value=await obtenerGrupo(detail.value.id);subName.value='';subEditing.value=null}catch(e){error.value=message(e)}}
async function removeSub(item:Subgrupo){if(!detail.value||item.items_count){error.value='No se puede eliminar un subgrupo con ítems asociados.';return}if(!confirm(`¿Eliminar “${item.nombre}”?`))return;try{await eliminarSubgrupo(detail.value.id,item.id);detail.value=await obtenerGrupo(detail.value.id)}catch(e){error.value=message(e)}}
async function addFeature(){if(!detail.value||!featureName.value.trim())return;try{await guardarCaracteristica(detail.value.id,featureName.value.trim());detail.value=await obtenerGrupo(detail.value.id);featureName.value=''}catch(e){error.value=message(e)}}
const message=(e:unknown)=>e instanceof Error?e.message:'No se pudo completar la operación.';onMounted(()=>load())
</script>
<template><div class="page"><nav><RouterLink to="/inicio">Inicio</RouterLink> / Administración / Logística / Grupos de ítems</nav><header class="hero"><div class="mark">GR</div><div><small>MIA · CATÁLOGO LOGÍSTICO</small><h1>Grupos de ítems</h1><p>Organiza materiales, activos y servicios con sus reglas contables.</p></div><b>{{total}} grupos</b><button @click="open()">+ Agregar grupo</button></header><p v-if="success" class="flash success">✓ {{success}}</p><p v-if="error" class="flash">{{error}}</p><section class="filters"><input v-model.trim="criterio" placeholder="Buscar por nombre del grupo" @keyup.enter="load(1)"><button @click="load(1)">Buscar</button><button class="soft" @click="criterio='';load(1)">Limpiar</button></section><div v-if="loading" class="empty">Cargando grupos…</div><div v-else-if="!rows.length" class="empty">No se encontraron grupos.</div>
<section v-else class="cards"><article v-for="item in rows" :key="item.id" :class="item.familia"><header><div class="icon">{{item.familia.toUpperCase()}}</div><div><small>{{item.familia_nombre}}</small><h2>{{item.nombre}}</h2></div><span v-if="item.etiqueta">ETIQUETABLE</span></header><div class="counts"><div><b>{{item.subgrupos_count}}</b><small>SUBGRUPOS</small></div><div><b>{{item.items_count}}</b><small>ÍTEMS</small></div><div><b>{{item.vida_util||0}}</b><small>VIDA ÚTIL</small></div><div><b>{{item.deprec||0}}%</b><small>DEPRECIACIÓN</small></div></div><div class="accounts"><span>Deprec.: {{item.debe_deprec||'—'}} / {{item.haber_deprec||'—'}}</span><span>Revaluac.: {{item.debe_revaluac||'—'}} / {{item.haber_revaluac||'—'}}</span></div><footer><button @click="open(item)">Modificar</button><button @click="show(item)">Subgrupos y características</button><button class="danger" :disabled="item.items_count>0" @click="remove(item)">Eliminar</button></footer></article></section><footer v-if="lastPage>1" class="pages"><button :disabled="page<=1" @click="load(page-1)">Anterior</button><span>{{page}} / {{lastPage}}</span><button :disabled="page>=lastPage" @click="load(page+1)">Siguiente</button></footer>
<div v-if="modal" class="backdrop" @mousedown.self="modal=false"><form class="dialog form-dialog" @submit.prevent="save"><header><div><small>CLASIFICACIÓN DE ÍTEMS</small><h2>{{editing?'Modificar':'Registrar'}} grupo</h2></div><button type="button" @click="modal=false">×</button></header><div class="grid"><label>Familia *<select v-model="form.familia" :disabled="Boolean(editing)"><option value="m">Materiales</option><option value="a">Activos</option><option value="s">Servicios</option></select></label><label>Nombre *<input v-model.trim="form.nombre" maxlength="255"></label><label>Vida útil (años)<input v-model.number="form.vida_util" type="number" min="1" max="99"></label><label>% depreciación<input :value="depreciation.toFixed(2)" disabled></label><label>Debe depreciación<input v-model.number="form.debe_deprec" type="number"></label><label>Haber depreciación<input v-model.number="form.haber_deprec" type="number"></label><label>Debe revaluación<input v-model.number="form.debe_revaluac" type="number"></label><label>Haber revaluación<input v-model.number="form.haber_revaluac" type="number"></label></div><label class="check"><input v-model="form.etiqueta" type="checkbox"> Los ítems requieren etiqueta patrimonial</label><footer><button type="button" class="soft" @click="modal=false">Cancelar</button><button :disabled="saving">Guardar grupo</button></footer></form></div>
<div v-if="detail" class="backdrop" @mousedown.self="detail=null"><section class="dialog detail"><header><div><small>{{detail.familia_nombre}}</small><h2>{{detail.nombre}}</h2></div><button @click="detail=null">×</button></header><div class="columns"><section><h3>Subgrupos</h3><div class="add"><input v-model.trim="subName" placeholder="Nombre del subgrupo" @keyup.enter="saveSub"><button @click="saveSub">{{subEditing?'Actualizar':'Agregar'}}</button></div><article v-for="sub in detail.subgrupos||[]" :key="sub.id"><div><b>{{sub.nombre}}</b><small>{{sub.items_count}} ítems asociados</small></div><button @click="editSub(sub)">Editar</button><button class="danger" :disabled="sub.items_count>0" @click="removeSub(sub)">Eliminar</button></article></section><section><h3>Características técnicas</h3><div class="add"><input v-model.trim="featureName" placeholder="Nueva característica" @keyup.enter="addFeature"><button @click="addFeature">Agregar</button></div><article v-for="feature in detail.caracteristicas||[]" :key="feature.id"><b>{{feature.nombre}}</b></article><p>Las características existentes se conservan porque pueden estar utilizadas en fichas técnicas.</p></section></div><footer><button @click="detail=null">Cerrar</button></footer></section></div></div></template>
<style scoped>
.page{--accent:#d64f83;color:#35464e}nav{margin-bottom:16px;color:#929fa5;font-size:.68rem}nav a{color:var(--accent);text-decoration:none}.hero{padding:20px 23px;display:flex;align-items:center;gap:14px;border-left:5px solid var(--accent);border-radius:12px;background:#fff}.mark{width:50px;height:50px;display:grid;place-items:center;border-radius:10px;color:#fff;background:var(--accent);font-size:.65rem;font-weight:700}.hero small,.cards small,.dialog small{color:var(--accent);font-size:.48rem;font-weight:800}.hero h1{margin:2px 0;font-size:1.3rem}.hero p{margin:0;color:#7e8a90;font-size:.67rem}.hero>b{margin-left:auto;font-size:.55rem}.hero button,.filters button,.pages button,.dialog button{padding:8px 10px;border:0;border-radius:6px;color:#fff;background:var(--accent);font-size:.52rem}.flash{padding:9px;border-radius:7px;color:#a64046;background:#fff0f0;font-size:.6rem}.flash.success{color:#287052;background:#edf9f3}.filters{margin-top:11px;padding:11px;display:flex;gap:6px;border-radius:9px;background:#fff}.filters input{flex:1}.soft{color:#64727a!important;background:#edf1f3!important}input,select{width:100%;box-sizing:border-box;padding:8px;border:1px solid #d9e0e3;border-radius:6px;font:inherit;font-size:.55rem}.empty{margin-top:11px;padding:45px;text-align:center;background:#fff;font-size:.6rem}.cards{margin-top:11px;display:grid;grid-template-columns:repeat(3,1fr);gap:10px}.cards article{padding:13px;border:1px solid #e0e5e7;border-top:4px solid #387fa5;border-radius:9px;background:#fff}.cards article.a{border-top-color:#2d9b68}.cards article.s{border-top-color:#df8d39}.cards article>header{display:flex;align-items:center;gap:8px}.icon{width:35px;height:35px;display:grid;place-items:center;border-radius:8px;color:#fff;background:#387fa5;font-weight:700}.a .icon{background:#2d9b68}.s .icon{background:#df8d39}.cards h2{margin:2px 0;font-size:.68rem}.cards header>span{margin-left:auto;padding:4px 6px;border-radius:8px;color:#287154;background:#e7f7ef;font-size:.43rem}.counts{margin:11px 0;display:grid;grid-template-columns:repeat(4,1fr);gap:5px}.counts div{padding:7px;text-align:center;border-radius:6px;background:#f5f7f8}.counts b,.counts small{display:block;font-size:.47rem}.counts b{font-size:.66rem}.accounts{display:flex;gap:4px;flex-wrap:wrap}.accounts span{padding:4px 6px;border-radius:7px;background:#f1edf8;font-size:.45rem}.cards footer{margin-top:10px;display:flex;gap:4px}.cards footer button{border:0;color:var(--accent);background:none;font-size:.47rem}.cards footer .danger{margin-left:auto;color:#b63f46}.cards footer button:disabled,.detail button:disabled{color:#adb4b7}.pages{margin-top:12px;display:flex;justify-content:center;align-items:center;gap:8px;font-size:.52rem}.backdrop{position:fixed;z-index:100;inset:0;padding:20px;display:grid;place-items:center;background:#172b3d88}.dialog{width:min(850px,100%);max-height:90vh;overflow:auto;padding:20px;box-sizing:border-box;border-radius:12px;background:#fff}.dialog>header{display:flex}.dialog h2{margin:2px 0 13px;font-size:1rem}.dialog>header button{margin-left:auto;color:#59666c;background:none;font-size:1.2rem}.grid,.columns{display:grid;grid-template-columns:1fr 1fr;gap:8px}.dialog label{font-size:.51rem}.dialog label input,.dialog label select{margin-top:4px}.check{margin-top:10px;display:flex;align-items:center;gap:6px}.check input{width:auto;margin:0!important}.dialog>footer{margin-top:12px;display:flex;justify-content:flex-end;gap:6px}.columns>section{padding:11px;border-radius:8px;background:#f5f7f8}.columns h3{margin:0 0 8px;font-size:.62rem}.add{display:flex;gap:5px}.columns article{margin-top:6px;padding:8px;display:flex;align-items:center;border-radius:6px;background:#fff;font-size:.51rem}.columns article div{display:grid}.columns article small{color:#849096}.columns article button{margin-left:auto;color:var(--accent);background:none}.columns article .danger{margin-left:3px;color:#b54047}.columns p{font-size:.48rem;color:#78858b}@media(max-width:900px){.hero{flex-wrap:wrap}.hero>b{margin-left:0}.cards,.grid,.columns{grid-template-columns:1fr}}
</style>
